#!/usr/bin/env python3
"""Build the ordinary 16KB release CAR and its identical engine ROM header."""
from pathlib import Path
import subprocess,hashlib,struct,json
h=Path(__file__).resolve().parent;root=h.parents[1];out=root/'dist/0.6.0';build=root/'build-release';out.mkdir(parents=True,exist_ok=True);build.mkdir(exist_ok=True)
for name in ['client','boot']:
 subprocess.run(['ca65',str(h/(name+'.s')),'-I',str(h),'-o',str(build/(name+'.o'))],cwd=h,check=True)
 subprocess.run(['ld65','-C',str(h/(name+'.cfg')),str(build/(name+'.o')),'-o',str(build/(name+'.bin')),'-Ln',str(build/(name+'.lbl')),'-m',str(build/(name+'.map'))],check=True)
client=(build/'client.bin').read_bytes();rom=bytearray((build/'boot.bin').read_bytes());assert len(client)==4096 and len(rom)==16384;rom[:4096]=client
labels={line.split()[2][1:]:int(line.split()[1],16)for line in(build/'client.lbl').read_text().splitlines()}
assert labels['frame_end']==0x2144 and rom[0x3ffa:]==bytes.fromhex('00a00004f0bf')
assert b'STEP 'not in rom and b'PAUSE 3'not in rom
assert 'pause_three'not in (h/'client.s').read_text()+(h/'boot.s').read_text()
car=b'CART'+struct.pack('>III',2,sum(rom)&0xffffffff,0)+rom;(out/'DOOM.CAR').write_bytes(car);(build/'release.rom').write_bytes(rom)
header='/* Generated by release/build_client.py. */\n#define RD_CLIENT_FRAME_END 0x2144\nstatic const unsigned char rd_boot_rom[16384]={\n'
header+='\n'.join(','.join(str(x)for x in rom[i:i+32])+','for i in range(0,len(rom),32))+'\n};\n';(h.parent/'firmware/client_rom.h').write_text(header)
meta={'version':'0.6.0','car_type':2,'car_bytes':len(car),'sha256':hashlib.sha256(car).hexdigest(),'diagnostic_screens':False,'timed_startup_pauses':False,'kernel_return':'0x2144','labels':labels};(out/'client-build.json').write_text(json.dumps(meta,indent=2)+'\n');print(json.dumps(meta,indent=2))
